public static void lookupWarehouseByCompany(FormStringControl _formControl, DataAreaId _company)
{
    Query                   query = new Query();
    QueryBuildDataSource    qbds;
    SysTableLookup          sysTableLookup;

    sysTableLookup = SysTableLookup::newParameters(tableNum(InventLocation), _formControl);

    sysTableLookup.addLookupField(fieldNum(InventLocation, InventLocationId), true);
    sysTableLookup.addLookupField(fieldNum(InventLocation, Name));

    qbds = query.addDataSource(tableNum(InventLocation));

    // Enable cross-company and filter to specific company
    query.allowCrossCompany(true);

    if (_company)
    {
        qbds.addRange(fieldNum(InventLocation, dataAreaId)).value(_company);
    }

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

public static container findSingleSiteAndWarehouseByUser(UserId _userId = curUserId())
{
    METUserSecurityWarehouseList      metUserSecurityWarehouseList;
    METUserSecurityGroupList          metUserSecurityGroupList;
    InventLocation                    inventLocation;
    InventSiteId                      singleSiteId;
    InventLocationId                  singleInventLocationId;
    boolean                           hasMoreThanOneRecord;

    while select InventLocationId from metUserSecurityWarehouseList
        group by InventLocationId
            where metUserSecurityWarehouseList.Company == curExt()
               && metUserSecurityWarehouseList.InventLocationId != ''
        exists join metUserSecurityGroupList
            where metUserSecurityGroupList.UserSecurityGroupId == metUserSecurityWarehouseList.UserSecurityGroupId
               && metUserSecurityGroupList.UserId == _userId

    {
        if (hasMoreThanOneRecord)
        {
            return conNull();
        }

        singleInventLocationId = metUserSecurityWarehouseList.InventLocationId;
        hasMoreThanOneRecord = true;
    }

    if (singleInventLocationId)
    {
        inventLocation = InventLocation::find(singleInventLocationId);
        singleSiteId = inventLocation.InventSiteId;
        return [singleSiteId, singleInventLocationId];
    }

    return conNull();
}

/// <summary>
/// Returns all site and warehouse combinations available to the specified user
/// based on warehouse security group assignments for the current company.
/// </summary>
/// <param name="_userId">
/// User ID to evaluate. Defaults to the current user.
/// </param>
/// <returns>
/// A container containing one or more nested containers in the format:
/// [[SiteId1, WarehouseId1], [SiteId2, WarehouseId2], ...].
/// Returns an empty container if no warehouses are assigned to the user.
/// </returns>
public static container findMultipleSiteAndWarehouseByUser(UserId _userId = curUserId())
{
    METUserSecurityWarehouseList      metUserSecurityWarehouseList;
    METUserSecurityGroupList          metUserSecurityGroupList;
    InventLocation                    inventLocation;
    container                         result;

    while select InventLocationId from metUserSecurityWarehouseList
    group by InventLocationId
        where metUserSecurityWarehouseList.Company == curExt()
           && metUserSecurityWarehouseList.InventLocationId != ''
    exists join metUserSecurityGroupList
        where metUserSecurityGroupList.UserSecurityGroupId == metUserSecurityWarehouseList.UserSecurityGroupId
           && metUserSecurityGroupList.UserId == _userId
    {
        inventLocation = InventLocation::find(
        metUserSecurityWarehouseList.InventLocationId);

        result += [[inventLocation.InventSiteId,
                metUserSecurityWarehouseList.InventLocationId]];
    }

    return result;
}

/// <summary>
///Validate write method
/// </summary>
/// <returns></returns>
public boolean validateWrite()
{
    boolean ret;

    ret = super();

    if (this.InventLocationId)
    {
        InventLocation inventLocation = InventLocation::findInLegalEntity(this.InventLocationId, this.company);
        if (!inventLocation)
        {
            ret = checkFailed(strFmt("@MET:WarehouseCompVal", this.InventLocationId, this.Company));
        }
    }

    return ret;
}
